INSERT INTO course_schedules (
  course_name,
  course_slug,
  course_type,
  start_date,
  end_date,
  start_time,
  end_time,
  timezone,
  time_slot,
  format,
  duration,
  instructor_name,
  instructor_image,
  price,
  original_price,
  currency,
  seats_available,
  total_seats,
  language,
  exam_included,
  status,
  is_weekend
)
SELECT
  nr.course_name,
  nr.course_slug,
  nr.course_type,
  nr.start_date::timestamptz,
  nr.end_date::timestamptz,
  nr.start_time::time,
  nr.end_time::time,
  nr.timezone,
  nr.time_slot,
  nr.format,
  nr.duration,
  nr.instructor_name,
  nr.instructor_image,
  nr.price,
  nr.original_price,
  nr.currency,
  nr.seats_available,
  nr.total_seats,
  nr.language,
  nr.exam_included,
  nr.status,
  nr.is_weekend
FROM new_rows nr
WHERE NOT EXISTS (
  SELECT 1
  FROM course_schedules cs
  WHERE cs.course_slug = nr.course_slug
    AND cs.start_date::date = nr.start_date::date
    AND cs.end_date::date = nr.end_date::date
    AND cs.start_time = nr.start_time::time
    AND cs.status = 'active'
)
ORDER BY nr.start_date, nr.course_slug;

-- Ensure existing active rows in this window use current pricing
UPDATE course_schedules
SET
  price = 515.00,
  original_price = 1030.00
WHERE course_slug IN ('leading-safe', 'scrum-master')
  AND start_date::date >= '2026-06-01'
  AND start_date::date <= '2026-09-30'
  AND status = 'active';

-- Verify inserted schedule window
SELECT
  course_slug,
  COUNT(*) AS total_rows,
  MIN(start_date::date) AS first_date,
  MAX(start_date::date) AS last_date
FROM course_schedules
WHERE start_date::date >= '2026-06-01'
  AND start_date::date <= '2026-09-30'
  AND status = 'active'
GROUP BY course_slug
ORDER BY course_slug;
